import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../../environments/environment';
import { Observable } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class FileService {
  private api = `${environment.apiUrl}/files`;
  private publicApi = `${environment.apiUrl}/public`;

  constructor(private http: HttpClient) {}

  // 🔹 Upload général (ancien système)
  uploadFile(title: string, type: number, file: File, classId: number) {
    const formData = new FormData();
    formData.append('title', title);
    formData.append('type', type.toString());
    formData.append('file', file);
    formData.append('classId', classId.toString());
    return this.http.post(`${this.api}/upload`, formData);
  }

  // 🔹 Upload d’un cahier pédagogique
  uploadCahierPedagogique(file: File, classId: number, fileName: string): Observable<any> {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('classId', classId.toString());
    formData.append('fileName', fileName || file.name);
    return this.http.post(`${this.api}/upload-cahier`, formData);
  }

  // 🔹 Récupération de tous les cahiers d’une classe
  getCahiersByClass(classId: number): Observable<any[]> {
    return this.http.get<any[]>(`${this.api}/by-class/${classId}`);
  }

  // 🔹 Récupération d’un cahier spécifique
  getCahierById(id: number): Observable<any> {
    return this.http.get<any>(`${this.api}/cahier/${id}`);
  }

  // 🔹 Suppression d’un cahier pédagogique
  deleteCahierPedagogique(id: number): Observable<any> {
    return this.http.delete(`${this.api}/delete-cahier/${id}`);
  }

  // 🧩 Fonctions publiques existantes (si tu en as besoin ailleurs)
  getFilesByProf(slug: string) {
    return this.http.get<any[]>(`${this.publicApi}/files/${slug}`);
  }

  getCahiersByProf(slug: string) {
    return this.http.get<any[]>(`${this.api}/cahiers/${slug}`);
  }

  deleteFile(id: number) {
    return this.http.delete(`${this.api}/${id}`);
  }
}
